    # Extend diagonal runs of matching colors through the background.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue

                # A crossing, non-background diagonal means this pair is part
                # of a compact motif rather than a ray.
                other1 = (r, nc)
                other2 = (nr, c)
                if grid[other1[0]][other1[1]] != bg and grid[other2[0]][other2[1]] != bg:
                    continue

                # Process only the start of each contiguous diagonal run.
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    rr += dr
                    cc += dc
                end_r, end_c = rr - dr, cc - dc

                for sr, sc, ar, ac in ((-dr, -dc, r, c), (dr, dc, end_r, end_c)):
                    rr, cc = ar + sr, ac + sc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc

    # A long vertical stroke also indicates a diagonal continuation from its end.
    for c in range(w):
        r = 0
        while r < h:
            color = grid[r][c]
            if color == bg:
                r += 1
                continue
            end = r + 1
            while end < h and grid[end][c] == color:
                end += 1
            if end - r >= 3:
                rr, cc = end - 1 + 1, c + 1
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += 1
                    cc += 1
            r = end

    return out
