        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue

                # Only start at the first cell of a same-color diagonal run.
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                # Ignore diagonal pairs embedded in a filled 2x2 motif.
                a, b = run[0], run[1]
                cross1 = grid[a[0]][b[1]]
                cross2 = grid[b[0]][a[1]]
                if cross1 != bg and cross2 != bg:
                    continue

                # Branched/orthogonally connected marks are not ray seeds.
                if any(
                    0 <= rr2 < h and 0 <= cc2 < w and grid[rr2][cc2] == color
                    for rr0, cc0 in (run[0], run[-1])
                    for rr2, cc2 in ((rr0-1, cc0), (rr0+1, cc0),
                                     (rr0, cc0-1), (rr0, cc0+1))
                ):
                    continue

                for (rr, cc), sr, sc in (
                    (run[0], -dr, -dc),
                    (run[-1], dr, dc),
                ):
                    rr += sr
                    cc += sc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
